#!/usr/bin/env node

/**
 * ═══════════════════════════════════════════════════════════════════════════════
 * RADIANCE PLATFORM — JAVASCRIPT BUNDLE & CHUNK AUDITOR
 * 
 * Inspects production build artifacts generated by Next.js in `.next/`
 * to accurately measure uncompressed and compressed chunk sizes, route footprints,
 * and verify adherence to performance budgets.
 * 
 * Establishes separate, explicit empirical budgets for:
 * 1. Shared Framework Chunks (React 19, Next.js 15, Webpack runtime)
 * 2. Route-Specific JavaScript (Code-split chunks unique to each route)
 * 3. Total Initial JavaScript (Shared + Route-specific JS)
 * 4. CSS Assets (Measured and reported separately from JS payloads)
 * ═══════════════════════════════════════════════════════════════════════════════
 */

import fs from "fs";
import path from "path";
import zlib from "zlib";

const NEXT_DIR = path.resolve(process.cwd(), ".next");
const APP_MANIFEST_PATH = path.join(NEXT_DIR, "app-build-manifest.json");

// Explicit Empirical Performance Budgets established from verified Next.js 15 App Router baseline
// Enforces separate Raw Size (uncompressed memory/parse cost) and Gzip Size (network transfer cost)
const SHARED_FRAMEWORK_BUDGET = {
  maxRawKb: 600,   // Max uncompressed JS for shared framework baseline
  maxGzipKb: 200,  // Max compressed transfer for shared framework baseline
};

const ROUTE_BUDGETS = {
  "/page": {
    name: "Landing Page",
    routeJs: { maxRawKb: 350, maxGzipKb: 120 },
    totalJs: { maxRawKb: 900, maxGzipKb: 300 },
  },
  "/chat/page": {
    name: "Chat Workspace",
    routeJs: { maxRawKb: 2000, maxGzipKb: 550 },
    totalJs: { maxRawKb: 2500, maxGzipKb: 750 },
  },
  "/layout": {
    name: "Root Layout Shell",
    routeJs: { maxRawKb: 50, maxGzipKb: 20 },
    totalJs: { maxRawKb: 650, maxGzipKb: 220 },
  },
  "/offline/page": {
    name: "Offline Fallback",
    routeJs: { maxRawKb: 200, maxGzipKb: 70 },
    totalJs: { maxRawKb: 750, maxGzipKb: 250 },
  },
  "/privacy/page": {
    name: "Privacy Fortress",
    routeJs: { maxRawKb: 250, maxGzipKb: 80 },
    totalJs: { maxRawKb: 800, maxGzipKb: 260 },
  },
  "/_not-found/page": {
    name: "Not Found (404)",
    routeJs: { maxRawKb: 50, maxGzipKb: 20 },
    totalJs: { maxRawKb: 650, maxGzipKb: 220 },
  },
};

function formatSize(bytes) {
  return `${(bytes / 1024).toFixed(1)} kB`;
}

function getFileSize(filePath) {
  try {
    const buffer = fs.readFileSync(filePath);
    const raw = buffer.length;
    const gzip = zlib.gzipSync(buffer).length;
    return { raw, gzip };
  } catch {
    return { raw: 0, gzip: 0 };
  }
}

async function runBundleAudit() {
  console.log("══════════════════════════════════════════════════════════════════════════════════════════════════════");
  console.log(" RADIANCE PLATFORM — JAVASCRIPT BUNDLE & CLIENT ASSET AUDIT");
  console.log("══════════════════════════════════════════════════════════════════════════════════════════════════════\n");

  if (!fs.existsSync(APP_MANIFEST_PATH)) {
    console.error("Error: .next/app-build-manifest.json not found. Run 'pnpm build' first.");
    process.exit(1);
  }

  const manifest = JSON.parse(fs.readFileSync(APP_MANIFEST_PATH, "utf8"));
  let hasBudgetViolation = false;

  // 1. Identify shared framework chunks loaded across application routes
  const chunkUsageCounts = {};
  const allRoutes = Object.keys(manifest.pages);
  const totalPages = allRoutes.length;

  for (const chunks of Object.values(manifest.pages)) {
    for (const chunk of chunks) {
      if (chunk.endsWith(".js")) {
        chunkUsageCounts[chunk] = (chunkUsageCounts[chunk] || 0) + 1;
      }
    }
  }

  // Chunks present in virtually every route are the shared framework runtime
  const sharedChunks = Object.keys(chunkUsageCounts).filter(
    (chunk) => chunkUsageCounts[chunk] >= totalPages - 2
  );

  let sharedRaw = 0;
  let sharedGzip = 0;

  for (const chunk of sharedChunks) {
    const { raw, gzip } = getFileSize(path.join(NEXT_DIR, chunk));
    sharedRaw += raw;
    sharedGzip += gzip;
  }

  const sharedRawKb = sharedRaw / 1024;
  const sharedGzipKb = sharedGzip / 1024;
  const sharedRawPass = sharedRawKb <= SHARED_FRAMEWORK_BUDGET.maxRawKb;
  const sharedGzipPass = sharedGzipKb <= SHARED_FRAMEWORK_BUDGET.maxGzipKb;

  console.log("── 1. SHARED FRAMEWORK BASELINE (Next.js 15, React 19, Webpack Runtime) ──");
  console.log(`Chunks: ${sharedChunks.length} files`);
  console.log(
    `Raw Size:  ${formatSize(sharedRaw).padEnd(10)} (Budget: < ${SHARED_FRAMEWORK_BUDGET.maxRawKb} kB) -> ${sharedRawPass ? "PASS" : "FAIL"}`
  );
  console.log(
    `Gzip Size: ${formatSize(sharedGzip).padEnd(10)} (Budget: < ${SHARED_FRAMEWORK_BUDGET.maxGzipKb} kB) -> ${sharedGzipPass ? "PASS" : "FAIL"}\n`
  );

  if (!sharedRawPass || !sharedGzipPass) {
    hasBudgetViolation = true;
  }

  // 2. Audit routes with explicit separation of Route-Specific JS, Total Initial JS, and CSS
  console.log("── 2. PER-ROUTE JAVASCRIPT & ASSET FOOTPRINT ──");
  console.log(
    `| Route               | Route JS (Raw / Gzip)   | Route Budget (Gzip) | Total JS (Raw / Gzip)     | Total Budget (Raw / Gzip)   | CSS Size (Raw / Gz) | Status |`
  );
  console.log(
    `|:--------------------|:------------------------|:--------------------|:--------------------------|:----------------------------|:--------------------|:-------|`
  );

  for (const [route, chunks] of Object.entries(manifest.pages)) {
    const jsChunks = chunks.filter((c) => c.endsWith(".js"));
    const cssChunks = chunks.filter((c) => c.endsWith(".css"));

    const routeOnlyJs = jsChunks.filter((c) => !sharedChunks.includes(c));

    let routeRaw = 0;
    let routeGzip = 0;
    for (const chunk of routeOnlyJs) {
      const { raw, gzip } = getFileSize(path.join(NEXT_DIR, chunk));
      routeRaw += raw;
      routeGzip += gzip;
    }

    let cssRaw = 0;
    let cssGzip = 0;
    for (const chunk of cssChunks) {
      const { raw, gzip } = getFileSize(path.join(NEXT_DIR, chunk));
      cssRaw += raw;
      cssGzip += gzip;
    }

    const totalRaw = sharedRaw + routeRaw;
    const totalGzip = sharedGzip + routeGzip;

    const budget = ROUTE_BUDGETS[route];
    let status = "PASS";
    let routeBudgetStr = "N/A";
    let totalBudgetStr = "N/A";

    if (budget) {
      routeBudgetStr = `< ${budget.routeJs.maxGzipKb} kB`;
      totalBudgetStr = `< ${budget.totalJs.maxRawKb}k / < ${budget.totalJs.maxGzipKb}k`;

      const routeGzipKb = routeGzip / 1024;
      const totalRawKb = totalRaw / 1024;
      const totalGzipKb = totalGzip / 1024;

      const routeOk = routeGzipKb <= budget.routeJs.maxGzipKb;
      const totalRawOk = totalRawKb <= budget.totalJs.maxRawKb;
      const totalGzipOk = totalGzipKb <= budget.totalJs.maxGzipKb;

      if (!routeOk || !totalRawOk || !totalGzipOk) {
        status = "FAIL (EXCEEDED)";
        hasBudgetViolation = true;
      }
    }

    const routeStr = `${formatSize(routeRaw)} / ${formatSize(routeGzip)}`;
    const totalStr = `${formatSize(totalRaw)} / ${formatSize(totalGzip)}`;
    const cssStr = cssChunks.length > 0 ? `${formatSize(cssRaw)} / ${formatSize(cssGzip)}` : "-";

    console.log(
      `| ${route.padEnd(19)} | ${routeStr.padEnd(23)} | ${routeBudgetStr.padEnd(19)} | ${totalStr.padEnd(25)} | ${totalBudgetStr.padEnd(27)} | ${cssStr.padEnd(19)} | ${status.padEnd(6)} |`
    );
  }

  console.log("\n══════════════════════════════════════════════════════════════════════════════════════════════════════");
  if (hasBudgetViolation) {
    console.error("❌ Bundle budget exceeded. Review chunk size regressions.");
    process.exit(1);
  } else {
    console.log("✅ All evaluated routes are within explicit Raw and Gzip performance budgets.");
    process.exit(0);
  }
}

runBundleAudit();
